import logo from "./logo.svg";
import "./App.css";

function App() {
  return (
    <div className="App">
      <ResponsiveNavbar />

      <div className="standard-section">
        <HeroArea
          onWatchVideo={(src) => {
            setVideoSrc(src);
            setVideoOpen(true);
          }}
        />
      </div>

      <div className="standard-section">
        <LatestAlbums albumList={albums} />
      </div>

      <div className="standard-section">
        <Shows />
      </div>

      <div className="standard-section">
        <Video
          onWatchVideo={(src) => {
            setVideoSrc(src);
            setVideoOpen(true);
          }}
        />
      </div>

      <div className="standard-section">
        <Bio />
      </div>

      {/* <BuyNowArea items={buyItems} />

